import{_ as a,o as i,c as n,a3 as t}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.5 Automatic All-Item Production","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"1\\\\.5智能全物品","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pRYbuAlRWdRJutvUjeqpKw","scope":"page"}},"headers":[],"relativePath":"src/page-pRYbuAlRWdRJutvUjeqpKw.md","filePath":"logistics/src/page-pRYbuAlRWdRJutvUjeqpKw.md","lastUpdated":null}'),s={name:"src/page-pRYbuAlRWdRJutvUjeqpKw.md"};function o(r,e,l,p,u,d){return i(),n("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-5智能全物品" aria-hidden="true"></span><h1 id="_1-5-automatic-all-item-production" tabindex="-1">1.5 Automatic All-Item Production <a class="header-anchor" href="#_1-5-automatic-all-item-production" aria-label="Permalink to &quot;1\\.5 Automatic All-Item Production&quot;">​</a></h1><blockquote><p>Source page ID: <code>pRYbuAlRWdRJutvUjeqpKw</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pRYbuAlRWdRJutvUjeqpKw" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-dsYpLcUvt4sJq232e5MyEh"></span></p><span class="logistics-source-anchor" id="概述" aria-hidden="true"></span><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This factory builds on <a href="./page-umMgUzRULECbKVLsX5rOlZ">1.5 Automatic Maximum Gross Production</a>, rearranging the Wuling main base and using the remaining space for an all-item production add-on.</p><p>Factory introduction video: <a href="https://www.bilibili.com/video/BV1NFe56uEdQ/" target="_blank" rel="noreferrer">Endfield: A Mature Factory Balances Itself | 1.5 Automatic All-Item Production</a></p><div class="callout"><p><span class="mark-red">For problems, first read the FAQ in the </span><a href="./page-umMgUzRULECbKVLsX5rOlZ">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> document. This page records only the differences between the all-item factory and the original maximum-gross-production factory.</span></p></div><p><strong>言: The blueprints here do not include the Jingyu Valley and Yinglung Pass updates. Install those two bases from the original document.</strong></p><p><span id="source-block-7Q3gAhFm23MJRYikatFJF7"></span></p><span class="logistics-source-anchor" id="蓝图码合集" aria-hidden="true"></span><h2 id="blueprint-codes" tabindex="-1">Blueprint Codes <a class="header-anchor" href="#blueprint-codes" aria-label="Permalink to &quot;Blueprint Codes&quot;">​</a></h2><p><span id="source-block-crdHOHmwMpyNJUQmsttjhE"></span></p><span class="logistics-source-anchor" id="开始拍蓝图前" aria-hidden="true"></span><h3 id="before-placing-any-blueprints" tabindex="-1"><strong>Before Placing Any Blueprints</strong> <a class="header-anchor" href="#before-placing-any-blueprints" aria-label="Permalink to &quot;**Before Placing Any Blueprints**&quot;">​</a></h3><p><span class="mark-red"><strong>Check your stored materials:</strong></span></p><p><span class="mark-red">10000+ Xiranite, 10000+ Cuprium, 2000+ Cuprium Part, 1000+ Amethyst Part, 1000+ Ferrium Part, 1000+ Origocrust, 1000+ Originium Ore, 500+ Jincao, 500+ Yazhen, 500+ Sandleaf Seed.</span></p><p><span class="mark-red">Enough facilities.</span></p><p><span class="mark-red"><strong>Check your base upgrades:</strong></span></p><p><span class="mark-red">We recommend maxing out all area expansions and Depot Bus Section upgrades. Yinglung Pass can actually do without the last two bus upgrades. You must unlock every technology except the turrets. Some technologies have prerequisite quests; complete any missing prerequisites yourself.</span></p><p><span class="mark-red"><strong>Check the North Wuling Exclusion Zone&#39;s Xiragen vents:</strong></span></p><p><span class="mark-red">Deliver Xiragen from at least 4 vents (80+ Xiragen/min) to the Yinglung Pass base.</span></p><p>The following are optional; completing them lets the factory automatically optimize to maximum capacity:</p><p>Reach development level 24 and connect all deposits: Originium Ore 540, Ferrium Ore 120, Cuprium Ore 510, Xiragen 150.</p><p>Transfer Dense Originium Powder beyond storage capacity.</p><p>Connect the Purification Node.</p><p>Use <span class="mark-red">conduit manifolds</span> to deliver surplus Xiragen from Yinglung Pass to the Wuling main base. If you skip this step, you can choose not to deliver Cedar Grove&#39;s 50 Xiragen.</p><p><span id="source-block-QY0Y5fLZcAXQZw6AZ3zMN3"></span></p><span class="logistics-source-anchor" id="应龙关分基地-与最大毛产相同" aria-hidden="true"></span><span class="logistics-source-anchor" id="yinglong-pass-sub-base-same-as-maximum-gross-production" aria-hidden="true"></span><h3 id="yinglung-pass-sub-base-same-as-maximum-gross-production" tabindex="-1">Yinglung Pass Sub-Base (Same as Maximum Gross Production) <a class="header-anchor" href="#yinglung-pass-sub-base-same-as-maximum-gross-production" aria-label="Permalink to &quot;Yinglung Pass Sub-Base (Same as Maximum Gross Production)&quot;">​</a></h3><p><a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-aZli93Lno95jxDGgn1OJj9">1.5 Automatic Maximum Gross Production</a></p><p>The content has been updated since the video, but placement is essentially unchanged. Place 01 flush against the top edge. For the later blueprints, mind bus-section connections and placement against edges; usually only one placement is possible. Conduit positions match the video.</p><p><span id="source-block-6auPmRtKBFFwDr1UFYAIKM"></span></p><span class="logistics-source-anchor" id="武陵主基地" aria-hidden="true"></span><h3 id="wuling-main-base" tabindex="-1">Wuling Main Base <a class="header-anchor" href="#wuling-main-base" aria-label="Permalink to &quot;Wuling Main Base&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-75c2dfaeed515d61.jpeg" alt="15 Automatic All-Item Production"></p><p>Arknights: Endfield blueprint [Wuling Upper Left 01], sharing code EF018OI342Eo515aUI73. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Upper Middle 02], sharing code EF010819Iu3aoiAIE179. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Upper Right 03], sharing code EF0170iU169ea5ueO0Ai. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Lower Right 04], sharing code EF01o5u82EOI46o7IieO. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Lower Middle 05], sharing code EF01A67i0a1U9E2E9ieO. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Lower Left 06], sharing code EF01E752iAUOeo183uIa. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling Purified Water], sharing code EF01I43oEO5u29975o08. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling All-Item Supplement], sharing code EF015i2OU7e4Au13eIoe. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Half-Rate Solid-Gas Filling], sharing code EF01U9eAa1670OO271a8. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [16-Level Oscillating Generation], sharing code EF01o5u82EOI46ooIieO. Copy it and use it in the game.</p><p><span id="source-block-4mvcuvXYicHquSbQwATrnY"></span></p><span class="logistics-source-anchor" id="天王坪分基地" aria-hidden="true"></span><span class="logistics-source-anchor" id="tianwangping-sub-base" aria-hidden="true"></span><h3 id="sky-king-flats-sub-base" tabindex="-1">Sky King Flats Sub-Base <a class="header-anchor" href="#sky-king-flats-sub-base" aria-label="Permalink to &quot;Sky King Flats Sub-Base&quot;">​</a></h3><p><a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5 Automatic Maximum Gross Production</a></p><p>Ignore the video&#39;s “Jingyu Valley 03” section and simply place 01 and 02 in order. The update changes the water-inlet location. The Inergen port is on the middle-right of the factory, viewed with the pool at the bottom.</p><p>Original blueprint codes, matching the video but potentially buggy in extreme cases; <span class="mark-red">we recommend the fixed maximum-gross-production version</span>:</p><p>Arknights: Endfield blueprint [Sky King Flats Upper 01], sharing code EF01u28IO543E03oAoOU. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Sky King Flats Lower A02], sharing code EF018OI342Eo5151UI73. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Sky King Flats Lower B03], sharing code EF013Eou5428OaUi0579. Copy it and use it in the game. (03 contains only water pipes.)</p><p><span id="source-block-vFGg7G1dpct2EvfCS4tQgI"></span></p><span class="logistics-source-anchor" id="首墩分基地" aria-hidden="true"></span><span class="logistics-source-anchor" id="shoudun-sub-base" aria-hidden="true"></span><h3 id="marker-stone-sub-base" tabindex="-1">Marker Stone Sub-Base <a class="header-anchor" href="#marker-stone-sub-base" aria-label="Permalink to &quot;Marker Stone Sub-Base&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-360bc82215d72603.jpeg" alt="15 Automatic All-Item Production"></p><p>Arknights: Endfield blueprint [Marker Stone Right 01], sharing code EF01u28IO543E038AoOU. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Marker Stone Left 02], sharing code EF01Oe4o17iu9I059oe4. Copy it and use it in the game.</p><p><span id="source-block-TWNbjFenQ8jvIjlY3KHizK"></span></p><span class="logistics-source-anchor" id="龙泡泡插件" aria-hidden="true"></span><h4 id="chubby-lung-add-on" tabindex="-1">Chubby Lung Add-On <a class="header-anchor" href="#chubby-lung-add-on" aria-label="Permalink to &quot;Chubby Lung Add-On&quot;">​</a></h4><p>Arknights: Endfield blueprint [Phase One 01], sharing code EF016u0Iuui10762O83e. Copy it and use it in the game.</p><p>After placement, we recommend turning off 2~4 main-base Cuprium Shredding Units and 1~2 Xiranite Reactor Crucibles. The end of the video shows which ones. Aim for Cuprium and Xiranite to be entirely consumed in the report.</p><p><span class="mark-grey"><em>“If your Xiranite and Cuprium have not been sucked dry, you have not squeezed the last bit of capacity out of the line.”</em></span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a0deb4f53acf50d3.q90-66ef4d4e985f0e57.webp" alt="15 Automatic All-Item Production"></p><p>Arknights: Endfield blueprint [Oversupplied Large Chubby Lung], sharing code EF012UO30A7o187oeIOo. Copy it and use it in the game.</p><p><span class="mark-red">20260923 19:00 update: Fixed a bug that could prevent the large Chubby Lung blueprint from reaching full rate under extreme conditions, no matter what you did. If you have not encountered this, replacement is optional.</span></p><p>Sorry about the ugly placement. <span class="mark-red"><strong>Connect one external Fluid Pump. After placement, inspect the Inergen pipe and ensure it connects to the previous blueprint&#39;s Inergen control port. Preferably collect all four Inergen vents at Marker Stone.</strong></span></p><div class="callout"><p><span class="mark-red">Note: a single full-rate large Chubby Lung line is insufficient to redeem the final 100 stock of T-Creds in the phase-two shop. Solutions include adding one full-rate small Chubby Lung line at the main base, switching off Cuprium Shredding Units/Xiranite crucibles yourself. The main base lacks enough Inergen for another full-rate large Chubby Lung line. (There is no space either.)</span></p><p>If you do not care about that tiny amount of T-Creds, ignore this.</p><p>For details, see the explanatory section of <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-Sp48AHGvwvLIbjxO4OoUeX">1.5 Automatic Maximum Gross Production</a>.</p></div><p>The oversupply ratio is the same as for small Chubby Lung. It actually requires 120 Cuprium + 60 Xiranite, oversupplied at 2:1. If you previously placed small Chubby Lung, replace it directly; no further machine switching is needed, provided the full-storage status of your other products has not changed.</p><p>Space constraints prevent using the optimal solid–liquid–gas route, so Xiranite consumption is 4.8/min above the best ratio.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-103506a8bfda153f.q90-e80cfaba2d02146f.webp" alt="15 Automatic All-Item Production"></p><p>If phase two requires an extra small Chubby Lung line at the main base, use my layout as a reference:</p><p>Move the “All-Item Supplement” facilities into an open area. The Canister facilities need Inergen and cannot move. Place a small Chubby Lung line in the original space. <span class="mark-red"><strong>Use the full-rate line below without oversupply. Do not oversupply it: that may instead slow down large Chubby Lung.</strong></span> Turn off all six Cuprium Shredding Units; if insufficient, turn off another 1~2. Decide how many Xiranite crucibles to switch off for your situation; I switched off two.</p><p>It is not a major problem if small Chubby Lung does not reach full rate: 5.5/min is enough. Surplus Chubby Lung from phase one may allow even less. Check the shop with a calculator to work out how much you need.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9834a5e37e0fc3c7.q90-0a805b790726418d.webp" alt="15 Automatic All-Item Production"></p><p>(The following event lines were built from recipes obtained by frame-by-frame inspection of the preview program; they are not oversupplied.)</p><p>Arknights: Endfield blueprint [Full-Rate Small Chubby Lung], sharing code EF018OI342Eo515uUI73. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Full-Rate Large Chubby Lung], sharing code EF01eaA7690i14I0oAi8. Copy it and use it in the game.</p><p><span id="source-block-SuCVE0S4vwQLSP738fBHEW"></span></p><span class="logistics-source-anchor" id="更新日志" aria-hidden="true"></span><h2 id="update-log" tabindex="-1">Update Log <a class="header-anchor" href="#update-log" aria-label="Permalink to &quot;Update Log&quot;">​</a></h2><p><span id="source-block-VFp0UKHHaASTk2JVQVaOOM"></span></p><h3 id="_20260923" tabindex="-1">20260923 <a class="header-anchor" href="#_20260923" aria-label="Permalink to &quot;20260923&quot;">​</a></h3><p>Added the oversupplied large Chubby Lung line.</p><p><span class="mark-red">19:00 update: Fixed a bug that could prevent the large Chubby Lung blueprint from reaching full rate under extreme conditions, no matter what you did. If you have not encountered this, replacement is optional.</span></p><p><span id="source-block-NRBpIel22Ky9YLQ0mpyTKR"></span></p><h3 id="_20260916" tabindex="-1">20260916 <a class="header-anchor" href="#_20260916" aria-label="Permalink to &quot;20260916&quot;">​</a></h3><p>Synchronized maximum-gross-production changes and added the oversupplied Chubby Lung line.</p><p><span id="source-block-ltwxzAIOVMbag5tadOAFHS"></span></p><h3 id="_20260915" tabindex="-1">20260915 <a class="header-anchor" href="#_20260915" aria-label="Permalink to &quot;20260915&quot;">​</a></h3><p>Official release.</p><blockquote><p>Translation note: The author name 言 is retained. Small/large Chubby Lung refer to the phase-one/phase-two event products.</p></blockquote></div>',1)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
